package com.grifplot.libros;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.util.*;
final class Store {
 final Context ctx; final File data; final ArrayList<Book> books=new ArrayList<>();final ArrayList<Category> categories=new ArrayList<>();final ArrayList<Folder> folders=new ArrayList<>();
 static class Book {String uri,title,author="",keywords="",category="books",source="",license="";String[] prices={"","","",""};long modified;boolean edited=false;Book(String u,String t){uri=u;title=t;}}
 static class Category {String id,name;Category(String i,String n){id=i;name=n;}}
 static class Folder {String uri,category;Folder(String u,String c){uri=u;category=c;}}
 Store(Context c){ctx=c;data=new File(c.getFilesDir(),"catalog.json");load();}
 synchronized void load(){try{JSONObject o=new JSONObject(read(data));JSONArray cs=o.getJSONArray("categories");for(int i=0;i<cs.length();i++){JSONObject x=cs.getJSONObject(i);categories.add(new Category(x.getString("id"),x.getString("name")));}JSONArray fs=o.getJSONArray("folders");for(int i=0;i<fs.length();i++){JSONObject x=fs.getJSONObject(i);folders.add(new Folder(x.getString("uri"),x.getString("category")));}JSONArray bs=o.getJSONArray("books");for(int i=0;i<bs.length();i++){JSONObject x=bs.getJSONObject(i);Book b=new Book(x.getString("uri"),x.getString("title"));b.author=x.optString("author");b.keywords=x.optString("keywords");b.category=x.optString("category","books");b.modified=x.optLong("modified");b.edited=x.optBoolean("edited");b.source=x.optString("source");b.license=x.optString("license");for(int p=0;p<4;p++)b.prices[p]=x.optString("price"+p);books.add(b);}}catch(Exception e){categories.clear();folders.clear();books.clear();categories.add(new Category("unheval","Exámenes UNHEVAL"));categories.add(new Category("books","Libros"));}}
 synchronized void save(){try{JSONObject o=new JSONObject();JSONArray cs=new JSONArray(),fs=new JSONArray(),bs=new JSONArray();for(Category c:categories)cs.put(new JSONObject().put("id",c.id).put("name",c.name));for(Folder f:folders)fs.put(new JSONObject().put("uri",f.uri).put("category",f.category));for(Book b:books)bs.put(new JSONObject().put("uri",b.uri).put("title",b.title).put("author",b.author).put("keywords",b.keywords).put("category",b.category).put("modified",b.modified).put("edited",b.edited).put("source",b.source).put("license",b.license).put("price0",b.prices[0]).put("price1",b.prices[1]).put("price2",b.prices[2]).put("price3",b.prices[3]));o.put("categories",cs).put("folders",fs).put("books",bs);File tmp=new File(data+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(o.toString().getBytes("UTF-8"));out.getFD().sync();}if(!tmp.renameTo(data))throw new IOException("No se pudo guardar el catálogo");}catch(Exception e){throw new IllegalStateException("No se pudo guardar el catálogo. Revisa el espacio disponible.",e);}}
 synchronized ArrayList<Book> snapshot(){return new ArrayList<>(books);}synchronized ArrayList<Category> cats(){return new ArrayList<>(categories);}
 synchronized String categoryName(String id){for(Category c:categories)if(c.id.equals(id))return c.name;return "Sin categoría";}
 synchronized void put(Book b){for(int i=0;i<books.size();i++)if(books.get(i).uri.equals(b.uri)){books.set(i,b);save();return;}books.add(b);save();}
 synchronized void deleteCategory(String id){categories.removeIf(c->c.id.equals(id));for(Book b:books)if(b.category.equals(id))b.category="";for(Folder f:folders)if(f.category.equals(id))f.category="";save();}
 String scan() {ArrayList<Folder> fs;Map<String,Book> old=new HashMap<>();synchronized(this){fs=new ArrayList<>(folders);for(Book b:books)old.put(b.uri,b);}ArrayList<Book> discovered=new ArrayList<>();Set<String> seen=new HashSet<>();int failures=0;for(Folder f:fs){ArrayList<Book> part=new ArrayList<>();try{Uri tree=Uri.parse(f.uri);walk(tree,DocumentsContract.getTreeDocumentId(tree),f.category,part,old,new HashSet<>(),0);for(Book b:part)if(seen.add(b.uri))discovered.add(b);}catch(Exception e){failures++;for(Book b:old.values())if(b.uri.startsWith(f.uri+"/document/"))if(seen.add(b.uri))discovered.add(b);}}synchronized(this){for(Book b:books)if(b.uri.startsWith("file:")&&new File(Uri.parse(b.uri).getPath()).exists()&&seen.add(b.uri))discovered.add(b);books.clear();books.addAll(discovered);save();}return discovered.size()+" PDF en el catálogo"+(failures>0?". No se pudo leer "+failures+" carpeta(s). Vuelve a conceder acceso en Administración.":". Catálogo actualizado.");}
 void walk(Uri tree,String id,String cat,ArrayList<Book> result,Map<String,Book> old,Set<String> visited,int depth)throws Exception{if(depth>40||!visited.add(id))return;if(result.size()>20000)throw new IOException("Demasiados archivos");Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=ctx.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_LAST_MODIFIED},null,null,null)){if(c==null)throw new IOException();while(c.moveToNext()){String cid=c.getString(0),name=c.getString(1),mime=c.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){walk(tree,cid,cat,result,old,visited,depth+1);continue;}if(!"application/pdf".equals(mime)&&!name.toLowerCase(Locale.ROOT).endsWith(".pdf"))continue;String uri=DocumentsContract.buildDocumentUriUsingTree(tree,cid).toString();Book b=old.get(uri);if(b==null){String t=name.replaceFirst("(?i)\\.pdf$","");String[] pieces=t.split(" - ",2);b=new Book(uri,pieces[0]);if(pieces.length>1)b.author=pieces[1];b.category=cat;}if(!b.edited&&(b.modified!=c.getLong(3)||b.modified==0)){String[] meta=PdfMetadata.read(ctx,uri);if(!meta[0].isEmpty())b.title=meta[0];if(!meta[1].isEmpty())b.author=meta[1];if(!meta[2].isEmpty())b.keywords=meta[2];}b.modified=c.getLong(3);result.add(b);}}}
 static String read(File f)throws IOException{try(InputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
}
